        t = str(v or '').lower()
        if ('drug' in t or 'mado' in t) and 'sensitivity' in t:
            score_col = c
        if 'clinical' in t and ('outcome' in t or 'efficacy' in t or 'response' in t):
            truth_col = c

def find_score(row):
    cols = [score_col] if score_col is not None else range(len(row))
    for c in cols:
        t = str(row[c] or '').strip().lower()
        if 'resistant' in t or t == 'resistance':
            return c, 0
        if 'sensitive' in t or 'sensitivity' in t:
            return c, 1
    return None, None

def find_truth(row):
    cols = [truth_col] if truth_col is not None else range(len(row))
    for c in cols:
        t = str(row[c] or '').strip()
        m = re.fullmatch(r'(PR|SD|PD)', t)
        if m:
            return c, m.group(1)
    for c, v in enumerate(row):
        m = re.search(r'\b(PR|SD|PD)\b', str(v or ''))
        if m:
            return c, m.group(1)
    return None, None

records = []
seen = set()
for r, row in enumerate(rows):
    row_text = ' '.join(str(v or '') for v in row)
    m = re.search(r'\b(K(?:OGS|OCO|OPT|OGB)-H\d+X)\b', row_text)
    if not m:
        continue
    sid = m.group(1)
    if sid in seen:
        continue
    sc, sval = find_score(row)
    tc, tval = find_truth(row)
